// Alt text Google can read: what it is, who shot it, where.
function shotAlt(shot){
  if(!shot) return "";
  const cat = { "fashion-editorial": "Fashion editorial", talent: "Model portrait", ecommerce: "Product photo" }[shot.cat];
  const what = shot.label && !/^(Portrait|Product|Model|Screenshot|Snaps|Single Page)$/.test(shot.label) ? shot.label : (cat || "Photo");
  return `${what}, photographed by Drew Neros${shot.city ? ` in ${shot.city}` : ""}`;
}

// Random-ish helper to fake AI analysis times
const wait = (ms) => new Promise(r => setTimeout(r, ms));

function deleteShot(id) {
  const idx = ALL_SHOTS.findIndex(s => s.id === id);
  if (idx === -1) return;
  ALL_SHOTS.splice(idx, 1);
  try { localStorage.setItem(_LS_KEY, JSON.stringify(ALL_SHOTS)); } catch {}
  window.dispatchEvent(new CustomEvent("dn:published"));
}

function updateShot(id, changes) {
  const shot = ALL_SHOTS.find(s => s.id === id);
  if (!shot) return;
  Object.assign(shot, changes);
  try { localStorage.setItem(_LS_KEY, JSON.stringify(ALL_SHOTS)); } catch {}
  window.dispatchEvent(new CustomEvent("dn:published"));
}

Object.assign(window, { shotAlt, CATEGORIES, ALL_SHOTS, CLIENTS, SERVICES, FAQ, makeShots, wait, publishFiles, deleteShot, updateShot });
